<?php require_once __DIR__.'/../includes/bootstrap.php';$token=$_GET['token']??$_POST['token']??'';$valid=false;if(is_string($token)&&preg_match('/^[a-f0-9]{64}$/',$token)){$q=db()->prepare('SELECT id,user_id FROM password_reset_tokens WHERE token_hash=? AND used_at IS NULL AND expires_at>UTC_TIMESTAMP()');$q->execute([hash('sha256',$token)]);$record=$q->fetch();$valid=(bool)$record;}
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$pw=$_POST['password']??'';$confirm=$_POST['confirm_password']??'';if(!$valid){flash('error','This reset link is invalid, expired, or already used.');}elseif(!password_valid($pw)||!hash_equals($pw,$confirm)){flash('error','Use a strong matching password and try again.');}else{$pdo=db();$pdo->beginTransaction();try{$q=$pdo->prepare('SELECT id,user_id FROM password_reset_tokens WHERE token_hash=? AND used_at IS NULL AND expires_at>UTC_TIMESTAMP() FOR UPDATE');$q->execute([hash('sha256',$token)]);$locked=$q->fetch();if(!$locked)throw new RuntimeException('Reset token is no longer valid.');$q=$pdo->prepare('UPDATE users SET password_hash=? WHERE id=?');$q->execute([password_digest($pw),$locked['user_id']]);$q=$pdo->prepare('UPDATE password_reset_tokens SET used_at=UTC_TIMESTAMP() WHERE user_id=? AND used_at IS NULL');$q->execute([$locked['user_id']]);$pdo->commit();flash('success','Password changed. Sign in with your new password.');redirect('/login.php');}catch(Throwable $e){$pdo->rollBack();error_log((string)$e);flash('error','The password could not be changed.');}}}
render_start('Choose a new password');if(!$valid){?><p class="lede">This link is invalid, expired, or already used.</p><a class="button" href="/forgot-password.php">Request another link</a><?php }else{?><p class="lede">Choose a strong new password for your account.</p><form method="post" data-validate><?=csrf_field()?><input type="hidden" name="token" value="<?=e($token)?>"><label>New password<span class="pw"><input type="password" name="password" autocomplete="new-password" minlength="12" required><button type="button" class="toggle">Show</button></span><small>At least 12 characters with upper and lower case, a number, and a symbol.</small></label><label>Confirm password<input type="password" name="confirm_password" autocomplete="new-password" required></label><button class="button">Save new password</button></form><?php }render_end();
